draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw bird
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t)*50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t)*50 - 20, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t)*50 + 20, H/2 + 30);
  ctx.stroke();

  // Draw wings
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t)*50 - 30 + Math.sin(t)*10, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t)*50 + 30 + Math.sin(t)*10, H/2 + 50);
  ctx.stroke();

  // Draw fish
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t)*100, H/2 + 100, 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t)*100, H/2 + 130);
  ctx.lineTo(W/2 + Math.cos(t)*100, H/2 + 160);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t)*100, H/2 + 130);
  ctx.lineTo(W/2 + Math.cos(t)*100 - 30, H/2 + 145);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t)*100, H/2 + 130);
  ctx.lineTo(W/2 + Math.cos(t)*100 + 30, H/2 + 145);
  ctx.stroke();

  // Draw tail
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t)*100, H/2 + 160);
  ctx.lineTo(W/2 + Math.cos(t)*100 - 20 + Math.cos(t)*10, H/2 + 180);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t)*100, H/2 + 160);
  ctx.lineTo(W/2 + Math.cos(t)*100 + 20 + Math.cos(t)*10, H/2 + 180);
  ctx.stroke();

  ctx.restore();
}
